// Reference blit. put_pixel() is the display's own pixel write.
static inline void onyx_draw_block_icon(int slot, bool on, int tile_x, int tile_y,
                                        void (*put_pixel)(int x, int y, uint16_t rgb565))
{
    const uint8_t *px = onyx_icons[slot];
    const uint16_t *pal = onyx_icon_palette[slot][on ? 0 : 1];
    const int x0 = tile_x + ONYX_ICON_TILE_DX, y0 = tile_y + ONYX_ICON_TILE_DY;
    for (int y = 0; y < ONYX_ICON_H; y++)
        for (int x = 0; x < ONYX_ICON_W; x++) {
            uint8_t i = px[y * ONYX_ICON_W + x];
            if (i) put_pixel(x0 + x, y0 + y, pal[i]);
        }
}
